//! `docs-gen`: the generated reference pages of the user documentation book (NFR-DOC-06, WP-S0.06).
//!
//! Two sources, both plain data files, so that this permissive-layer tool links no GPL crate:
//!
//! - the command-parameter JSON Schemas of `ew-commands` (`crates/ew-commands/schemas/`, generated by that
//!   crate's `schemas` test) give one page per command under `docs/book/src/reference/commands/`;
//! - the rule catalogue snapshot of `ew-checks` (`crates/ew-checks/catalogue/rules.json`, generated by that
//!   crate's `catalogue` test from the rule registry and the shipped schemes) gives one page per rule pack under
//!   `docs/book/src/reference/rules/`.
//!
//! The generated pages are committed. `docs-gen --check` changes nothing and fails when a committed page
//! differs, is missing or is stale, like `symbols-qet10 --check`. The two lists of generated entries in
//! `docs/book/src/SUMMARY.md` are rewritten too: every line that links into `reference/commands/` or
//! `reference/rules/` (the index pages excepted) is regenerated below the line that links the index page.
//!
//! The pages hold what the sources hold: a command's description, registry entry and parameter types; a rule's
//! ID, code, title, pack, kind, modes, severities, scope, supersessions and scheme membership. Message templates,
//! quick fixes and standard references are not in either source yet (the engine builds its messages at run time),
//! so the rule pages link the catalogue of doc 15 §4 for them.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::path::Path;

use anyhow::{Context, Result, bail};
use serde::Deserialize;
use serde_json::{Map, Value};

/// The command-parameter schemas (`index.json` and `<name>.schema.json`).
const SCHEMA_DIR: &str = "crates/ew-commands/schemas";
/// The rule catalogue snapshot of `ew-checks`.
const CATALOGUE: &str = "crates/ew-checks/catalogue/rules.json";
/// The book's Markdown sources, relative to the workspace root.
const BOOK_SRC: &str = "docs/book/src";
/// Generated command pages, relative to [`BOOK_SRC`].
const COMMANDS_DIR: &str = "reference/commands";
/// Generated rule pages, relative to [`BOOK_SRC`].
const RULES_DIR: &str = "reference/rules";
/// The book's table of contents, relative to [`BOOK_SRC`].
const SUMMARY: &str = "SUMMARY.md";
/// Where repository files are linked from the book (not relative: the built book holds no design documents).
const REPO_BLOB: &str = "https://github.com/Ironkode787/ElektraWatt/blob/main/";
/// Doc 15 (checks): the section of the rule catalogue per pack, with the heading's anchor.
const PACK_SECTIONS: &[(&str, &str, &str)] = &[
    ("EW-CORE", "4.2 EW-CORE", "42-ew-core"),
    (
        "EW-IEC81346",
        "4.3 EW-IEC81346: designations and numbering",
        "43-ew-iec81346-designations-and-numbering",
    ),
    ("EW-PLC", "4.5.1 EW-PLC", "451-ew-plc"),
    ("EW-POT", "4.4 EW-TERM and EW-POT", "44-ew-term-and-ew-pot"),
    ("EW-REL", "4.8 EW-REL: release gate", "48-ew-rel-release-gate"),
    ("EW-TERM", "4.4 EW-TERM and EW-POT", "44-ew-term-and-ew-pot"),
];

/// Rust constants that command descriptions name (`[`NAME`]`), as (name, source file): the page lists the values.
const LISTED_CONSTS: &[(&str, &str)] = &[("SETTABLE_SUPPLY", "crates/ew-commands/src/commands/supply.rs")];

/// The entries a generated page list adds to `SUMMARY.md`: link text and path relative to the book source.
type SummaryItems = Vec<(String, String)>;

/// Everything `docs-gen` writes.
struct Generated {
    /// Page path relative to [`BOOK_SRC`] to its text.
    files: BTreeMap<String, String>,
    commands: SummaryItems,
    packs: SummaryItems,
}

/// What `docs-gen` would write.
struct Plan {
    /// Page path relative to [`BOOK_SRC`] to its wanted text, `SUMMARY.md` included.
    wanted: BTreeMap<String, String>,
    /// The pages whose committed text differs or is missing.
    differing: Vec<String>,
    /// The committed pages in the generated directories that no source gives.
    stale: Vec<String>,
    commands: usize,
    packs: usize,
}

fn plan(root: &Path) -> Result<Plan> {
    let generated = generate(root)?;
    let mut wanted: BTreeMap<String, String> = generated.files.clone();
    let summary_path = root.join(BOOK_SRC).join(SUMMARY);
    let summary =
        read_lf(&summary_path)?.with_context(|| format!("{} is missing", summary_path.display()))?;
    wanted.insert(
        SUMMARY.to_owned(),
        rewrite_summary(&summary, &generated.commands, &generated.packs)?,
    );

    let mut differing = Vec::new();
    for (rel, text) in &wanted {
        if read_lf(&root.join(BOOK_SRC).join(rel))?.as_deref() != Some(text.as_str()) {
            differing.push(rel.clone());
        }
    }
    let mut stale = Vec::new();
    for dir in [COMMANDS_DIR, RULES_DIR] {
        let Ok(entries) = std::fs::read_dir(root.join(BOOK_SRC).join(dir)) else {
            continue;
        };
        for entry in entries.flatten() {
            let rel = format!("{dir}/{}", entry.file_name().to_string_lossy());
            if !wanted.contains_key(&rel) {
                stale.push(rel);
            }
        }
    }
    stale.sort();
    Ok(Plan {
        wanted,
        differing,
        stale,
        commands: generated.commands.len(),
        packs: generated.packs.len(),
    })
}

/// The violations of `docs-gen --check` (NFR-DOC-06): one per page that differs, is missing or is stale.
fn violations_of(plan: &Plan) -> Vec<String> {
    let differing = plan
        .differing
        .iter()
        .map(|rel| format!("{BOOK_SRC}/{rel} differs; run `cargo xtask docs-gen`"));
    let stale = plan
        .stale
        .iter()
        .map(|rel| format!("{BOOK_SRC}/{rel} is stale (no source); run `cargo xtask docs-gen`"));
    differing.chain(stale).collect()
}

/// The violations of `docs-gen --check` for the repository at `root`: the generated pages, and the work-package
/// counts that the plan states by hand (`plan_counts.rs`).
pub(crate) fn violations(root: &Path) -> Result<Vec<String>> {
    let mut found = violations_of(&plan(root)?);
    found.extend(crate::plan_counts::violations(root)?);
    Ok(found)
}

/// `docs-gen [--check]` for the repository at `root`.
pub(crate) fn run(root: &Path, check: bool) -> Result<bool> {
    let plan = plan(root)?;
    // The plan's hand-written WP counts: checked in both modes, never rewritten (they are prose).
    let counts = crate::plan_counts::violations(root)?;
    if check {
        let mut violations = violations_of(&plan);
        violations.extend(counts);
        if violations.is_empty() {
            println!(
                "docs-gen: ok ({} commands, {} rule packs)",
                plan.commands, plan.packs
            );
            return Ok(true);
        }
        eprintln!("docs-gen: {} problem(s)", violations.len());
        for v in &violations {
            eprintln!("  - {v}");
        }
        return Ok(false);
    }

    for rel in &plan.differing {
        let path = root.join(BOOK_SRC).join(rel);
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
        }
        std::fs::write(&path, &plan.wanted[rel]).with_context(|| format!("writing {}", path.display()))?;
    }
    for rel in &plan.stale {
        let path = root.join(BOOK_SRC).join(rel);
        std::fs::remove_file(&path).with_context(|| format!("removing {}", path.display()))?;
    }
    println!(
        "docs-gen: {} page(s) written, {} removed, {} unchanged",
        plan.differing.len(),
        plan.stale.len(),
        plan.wanted.len() - plan.differing.len()
    );
    if !counts.is_empty() {
        eprintln!(
            "docs-gen: {} stated WP count(s) differ from docs/plan/work-packages.csv; fix them by hand",
            counts.len()
        );
        for v in &counts {
            eprintln!("  - {v}");
        }
        return Ok(false);
    }
    Ok(true)
}

/// The text of a file with LF line ends; `None` when it does not exist.
fn read_lf(path: &Path) -> Result<Option<String>> {
    match std::fs::read_to_string(path) {
        Ok(text) => Ok(Some(text.replace("\r\n", "\n"))),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e).with_context(|| format!("reading {}", path.display())),
    }
}

/// Reads and parses a JSON file under `root`.
fn read_json(root: &Path, rel: &str) -> Result<Value> {
    let text = read_lf(&root.join(rel))?.with_context(|| format!("{rel} is missing"))?;
    serde_json::from_str(&text).with_context(|| format!("parsing {rel}"))
}

fn generate(root: &Path) -> Result<Generated> {
    let mut files = BTreeMap::new();
    let commands = command_pages(root, &mut files)?;
    let packs = rule_pages(root, &mut files)?;
    Ok(Generated {
        files,
        commands,
        packs,
    })
}

// ---------------------------------------------------------------------------------------------------------------
// SUMMARY.md

/// The `SUMMARY.md` text with the generated entries replaced: every line that links into `reference/commands/` or
/// `reference/rules/` other than the index pages is dropped, then the entries are inserted, indented two spaces
/// deeper, below the line that links the index page of their directory.
fn rewrite_summary(text: &str, commands: &SummaryItems, packs: &SummaryItems) -> Result<String> {
    let commands_index = format!("({COMMANDS_DIR}/index.md)");
    let rules_index = format!("({RULES_DIR}/index.md)");
    let is_generated = |line: &str| {
        [COMMANDS_DIR, RULES_DIR].iter().any(|dir| {
            let prefix = format!("]({dir}/");
            line.contains(&prefix) && !line.contains(&format!("]({dir}/index.md)"))
        })
    };
    let (mut out, mut saw_commands, mut saw_rules) = (String::new(), false, false);
    for line in text.lines().filter(|l| !is_generated(l)) {
        out.push_str(line);
        out.push('\n');
        let indent = line.len() - line.trim_start().len();
        let items = if line.contains(&commands_index) {
            saw_commands = true;
            commands
        } else if line.contains(&rules_index) {
            saw_rules = true;
            packs
        } else {
            continue;
        };
        for (title, link) in items {
            let _ = writeln!(out, "{}- [{title}]({link})", " ".repeat(indent + 2));
        }
    }
    if !saw_commands || !saw_rules {
        bail!("{BOOK_SRC}/{SUMMARY} must link {COMMANDS_DIR}/index.md and {RULES_DIR}/index.md");
    }
    Ok(out)
}

// ---------------------------------------------------------------------------------------------------------------
// Text helpers

/// The line of a generated page that says where it comes from.
fn header(source: &str) -> String {
    format!(
        "<!-- Generated by `cargo xtask docs-gen` from {source}. Do not edit: change the source and regenerate. -->"
    )
}

/// The link to a repository directory.
fn repo_tree_link(path: &str) -> String {
    format!("{}{path}", REPO_BLOB.replace("/blob/", "/tree/"))
}

/// The link to a repository file, with an optional anchor.
fn repo_link(path: &str, anchor: Option<&str>) -> String {
    match anchor {
        Some(a) => format!("{REPO_BLOB}{path}#{a}"),
        None => format!("{REPO_BLOB}{path}"),
    }
}

/// Description text made safe for Markdown: rustdoc intra-doc links (`` [`X`] ``) become code spans, and `<`
/// outside code spans is escaped so that placeholders such as `<kind>` are not read as HTML.
fn clean(text: &str) -> String {
    let text = text.replace("[`", "`").replace("`]", "`");
    let mut out = String::with_capacity(text.len());
    let mut in_code = false;
    for c in text.chars() {
        match c {
            '`' => {
                in_code = !in_code;
                out.push(c);
            }
            '<' if !in_code => out.push_str("&lt;"),
            _ => out.push(c),
        }
    }
    out
}

/// Text for a table cell: one line, `|` escaped.
fn cell(text: &str) -> String {
    clean(text).replace('\n', " ").replace('|', "\\|")
}

/// The first paragraph of a description, on one line.
fn first_paragraph(text: &str) -> String {
    text.split("\n\n").next().unwrap_or("").replace('\n', " ")
}

/// The anchor `mdBook` gives a heading (lower case, punctuation dropped).
fn anchor(name: &str) -> String {
    name.chars()
        .filter(|c| c.is_alphanumeric() || *c == '-' || *c == '_' || *c == ' ')
        .collect::<String>()
        .to_lowercase()
        .replace(' ', "-")
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key).and_then(Value::as_str).unwrap_or("")
}

/// Joins words as "a, b or c".
fn join_or(items: &[String]) -> String {
    match items {
        [] => String::new(),
        [one] => one.clone(),
        [init @ .., last] => format!("{} or {last}", init.join(", ")),
    }
}

// ---------------------------------------------------------------------------------------------------------------
// Commands

/// The string elements of `const <name>: &[&str] = &[...]` in the source file `rel`, as inline code joined by commas.
fn const_strings(root: &Path, rel: &str, name: &str) -> Result<String> {
    let text = read_lf(&root.join(rel))?.with_context(|| format!("{rel} is missing"))?;
    let start = text
        .find(&format!("const {name}:"))
        .with_context(|| format!("{rel}: no `const {name}`"))?;
    let item = &text[start..];
    let item = &item[..item
        .find(';')
        .with_context(|| format!("{rel}: `const {name}` has no end"))?];
    let values: Vec<String> = item
        .split('"')
        .skip(1)
        .step_by(2)
        .map(|v| format!("`{v}`"))
        .collect();
    if values.is_empty() {
        bail!("{rel}: `const {name}` lists no strings");
    }
    Ok(values.join(", "))
}

fn command_pages(root: &Path, files: &mut BTreeMap<String, String>) -> Result<SummaryItems> {
    let mut consts = BTreeMap::new();
    for (name, rel) in LISTED_CONSTS {
        consts.insert(*name, const_strings(root, rel, name)?);
    }
    let index = read_json(root, &format!("{SCHEMA_DIR}/index.json"))?;
    let entries = index
        .get("commands")
        .and_then(Value::as_array)
        .with_context(|| format!("{SCHEMA_DIR}/index.json has no `commands` list"))?;
    let mut rows = String::new();
    let mut items = SummaryItems::new();
    let mut names = BTreeSet::new();
    for entry in entries {
        let name = str_of(entry, "name");
        if name.is_empty() || !names.insert(name.to_owned()) {
            bail!("{SCHEMA_DIR}/index.json: a command without a name or named twice ({name:?})");
        }
        let file = str_of(entry, "schema");
        let schema = read_json(root, &format!("{SCHEMA_DIR}/{file}"))?;
        let page = command_page(entry, &schema, &consts);
        let summary = first_paragraph(str_of(&schema, "description"));
        let summary = summary
            .strip_prefix(&format!("`{name}`: "))
            .unwrap_or(&summary)
            .to_owned();
        let _ = writeln!(
            rows,
            "| [`{name}`]({name}.md) | {} | {} | {} | {} |",
            cell(&summary),
            str_of(entry, "cost"),
            str_of(entry, "exposure"),
            str_of(entry, "stability"),
        );
        files.insert(format!("{COMMANDS_DIR}/{name}.md"), page);
        items.push((format!("`{name}`"), format!("{COMMANDS_DIR}/{name}.md")));
    }

    let mut page = String::new();
    let _ = write!(
        page,
        "# Command reference\n\n{}\n\n\
         A command is the one way to change a project (`Command` → `Transaction` → `Op`). The same command runs from the \
         user interface, from a command log replayed by `ew apply`, from scripts and from the Session API. Each page \
         below gives the command's registry entry, its parameters with types and constraints, and the exit codes of \
         `ew apply`.\n\n\
         {} commands, from the parameter schemas in [`{SCHEMA_DIR}`]({}). The catalogue of the command registry is \
         [doc 17 §2.1]({}).\n\n\
         | Command | Summary | Cost | Exposure | Stability |\n|---|---|---|---|---|\n{rows}",
        header(&format!("{SCHEMA_DIR}/")),
        items.len(),
        repo_tree_link(SCHEMA_DIR),
        repo_link("docs/design/17-extensibility.md", Some("21-command-registry")),
    );
    files.insert(format!("{COMMANDS_DIR}/index.md"), page);
    Ok(items)
}

/// The page of one command.
fn command_page(entry: &Value, schema: &Value, consts: &BTreeMap<&str, String>) -> String {
    let name = str_of(entry, "name");
    let mut description = str_of(schema, "description").to_owned();
    for (constant, values) in consts {
        description = description.replace(&format!("[`{constant}`]"), values);
    }
    let mut out = String::new();
    let _ = write!(
        out,
        "# `{name}`\n\n{}\n\n{}\n\n",
        header(&format!("{SCHEMA_DIR}/{}", str_of(entry, "schema"))),
        clean(&description),
    );

    let aliases: Vec<String> = entry
        .get("aliases")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(Value::as_str)
                .map(|s| format!("`{s}`"))
                .collect()
        })
        .unwrap_or_default();
    let _ = write!(
        out,
        "## Registry entry\n\n| Item | Value |\n|---|---|\n\
         | Name | `{name}` |\n\
         | Parameters version | {} |\n\
         | Cost | {} |\n\
         | Undoable | {} |\n\
         | Exposure | {} |\n\
         | Stability | {} |\n\
         | Confirmation | {} |\n\
         | Aliases | {} |\n\
         | Parameter schema | [`{}`]({}) |\n\n",
        entry
            .get("params_version")
            .map_or_else(String::new, Value::to_string),
        str_of(entry, "cost"),
        if entry.get("undoable").and_then(Value::as_bool) == Some(true) {
            "yes"
        } else {
            "no"
        },
        str_of(entry, "exposure"),
        str_of(entry, "stability"),
        str_of(entry, "confirmation"),
        if aliases.is_empty() {
            "none".to_owned()
        } else {
            aliases.join(", ")
        },
        str_of(entry, "schema"),
        repo_link(&format!("{SCHEMA_DIR}/{}", str_of(entry, "schema")), None),
    );

    let defs = schema
        .get("$defs")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let mut used = BTreeSet::new();
    out.push_str("## Parameters\n\n");
    match properties_table(schema, &defs, &mut used) {
        Some(table) => out.push_str(&table),
        None => out.push_str("The command takes no parameters.\n"),
    }
    out.push('\n');

    // The definitions the parameters name, and those they name in turn.
    let mut done = BTreeSet::new();
    let mut types = String::new();
    while let Some(def) = used.iter().find(|d| !done.contains(*d)).cloned() {
        done.insert(def.clone());
        if let Some(schema) = defs.get(&def) {
            types.push_str(&definition(&def, schema, &defs, &mut used));
        }
    }
    if !types.is_empty() {
        let _ = write!(out, "## Types\n\n{types}");
    }

    out.push_str("## Exit codes\n\n");
    let _ = write!(
        out,
        "A command runs as one line of a command log replayed by `ew apply` ([doc 17 §3.5]({})). The exit code of \
         `ew apply` is:\n\n\
         | Code | Meaning |\n|---|---|\n\
         | 0 | The line committed as one transaction. |\n\
         | 1 | A prevent rule or the command's own domain rule refused the line (`Prevented`, `Rejected`); without `--one-step` the lines before it stay committed and are saved, with `--one-step` nothing is saved. |\n\
         | 2 | Anything else stops the replay: invalid parameters, a missing record, an unresolvable reference, an open, lock or save error. |\n\n\
         The codes of every subcommand are in [doc 17 §3.2]({}).\n",
        repo_link("docs/design/17-extensibility.md", Some("35-command-logs-ewcmd")),
        repo_link("docs/design/17-extensibility.md", Some("32-exit-codes")),
    );
    if str_of(entry, "cost") == "bulk" {
        out.push_str(
            "\nThis is a bulk command: a log line runs it as a preview first and commits the previewed result \
             ([doc 17 §3.5](",
        );
        out.push_str(&repo_link(
            "docs/design/17-extensibility.md",
            Some("35-command-logs-ewcmd"),
        ));
        out.push_str(")).\n");
    }
    if !str_of(entry, "exposure").is_empty() && str_of(entry, "exposure") != "edit" {
        let _ = write!(
            out,
            "\nExposure class `{}`: [doc 17 §2.3]({}) says whether a command log may run it.\n",
            str_of(entry, "exposure"),
            repo_link(
                "docs/design/17-extensibility.md",
                Some("23-origins-and-exposure-classes")
            ),
        );
    }
    out
}

/// The table of an object schema's properties; `None` when it has none.
fn properties_table(
    schema: &Value,
    defs: &Map<String, Value>,
    used: &mut BTreeSet<String>,
) -> Option<String> {
    let props = schema.get("properties").and_then(Value::as_object)?;
    if props.is_empty() {
        return None;
    }
    let required: BTreeSet<&str> = schema
        .get("required")
        .and_then(Value::as_array)
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let mut out = String::from("| Name | Type | Required | Default | Description |\n|---|---|---|---|---|\n");
    for (name, prop) in props {
        let description = match str_of(prop, "description") {
            "" => prop
                .get("$ref")
                .and_then(Value::as_str)
                .and_then(|r| defs.get(r.rsplit('/').next().unwrap_or("")))
                .map(|d| first_paragraph(str_of(d, "description")))
                .unwrap_or_default(),
            d => d.to_owned(),
        };
        let default = prop.get("default").map_or_else(String::new, |d| {
            format!("`{}`", d.to_string().replace('|', "\\|"))
        });
        let _ = writeln!(
            out,
            "| `{name}` | {} | {} | {default} | {} |",
            shape(prop, used),
            if required.contains(name.as_str()) {
                "yes"
            } else {
                "no"
            },
            cell(&description),
        );
    }
    Some(out)
}

/// The section of one definition of a schema's `$defs`.
fn definition(name: &str, schema: &Value, defs: &Map<String, Value>, used: &mut BTreeSet<String>) -> String {
    let mut out = format!("### {name}\n\n");
    let description = str_of(schema, "description");
    if !description.is_empty() {
        let _ = write!(out, "{}\n\n", clean(description));
    }
    let alternatives = ["oneOf", "anyOf"]
        .iter()
        .find_map(|k| schema.get(*k).and_then(Value::as_array));
    if let Some(alts) = alternatives {
        if alts.iter().all(|a| a.get("const").is_some()) {
            out.push_str("| Value | Meaning |\n|---|---|\n");
            for alt in alts {
                let value = alt.get("const").map_or_else(String::new, Value::to_string);
                let meaning = str_of(alt, "description");
                // The generated description of a unit variant only repeats its name.
                let meaning = if meaning.trim_matches(|c| c == '`' || c == '.') == value.trim_matches('"') {
                    ""
                } else {
                    meaning
                };
                let _ = writeln!(out, "| `{}` | {} |", value.replace('|', "\\|"), cell(meaning));
            }
            out.push('\n');
        } else {
            out.push_str("One of the following forms:\n\n");
            for (i, alt) in alts.iter().enumerate() {
                let description = str_of(alt, "description");
                let _ = write!(out, "{}. **Form {}**", i + 1, i + 1);
                if !description.is_empty() {
                    let _ = write!(out, ": {}", clean(&first_paragraph(description)));
                }
                let _ = write!(out, "\n\n   Shape: {}\n\n", shape(alt, used));
                if let Some(table) = properties_table(alt, defs, used) {
                    for line in table.lines() {
                        let _ = writeln!(out, "   {line}");
                    }
                    out.push('\n');
                }
            }
        }
        return out;
    }
    if let Some(table) = properties_table(schema, defs, used) {
        out.push_str(&table);
        out.push('\n');
        return out;
    }
    let _ = write!(out, "Type: {}\n\n", shape(schema, used));
    if let Some(pattern) = schema.get("pattern").and_then(Value::as_str) {
        let _ = write!(out, "Pattern: `{}`\n\n", pattern.replace('`', "'"));
    }
    out
}

/// A compact description of a schema's type for a table cell. Definitions it names are added to `used`.
fn shape(schema: &Value, used: &mut BTreeSet<String>) -> String {
    let Some(obj) = schema.as_object() else {
        return if schema == &Value::Bool(false) {
            "nothing".to_owned()
        } else {
            "any JSON value".to_owned()
        };
    };
    if let Some(r) = obj.get("$ref").and_then(Value::as_str) {
        let name = r.rsplit('/').next().unwrap_or(r);
        used.insert(name.to_owned());
        return format!("[`{name}`](#{})", anchor(name));
    }
    if let Some(c) = obj.get("const") {
        return code(&c.to_string());
    }
    if let Some(values) = obj.get("enum").and_then(Value::as_array) {
        let values: Vec<String> = values.iter().map(|v| code(&v.to_string())).collect();
        return format!("one of {}", values.join(", "));
    }
    for key in ["oneOf", "anyOf"] {
        let Some(alts) = obj.get(key).and_then(Value::as_array) else {
            continue;
        };
        if alts.iter().all(|a| a.get("const").is_some()) {
            let values: Vec<String> = alts
                .iter()
                .filter_map(|a| a.get("const"))
                .map(|c| code(&c.to_string()))
                .collect();
            return format!("one of {}", values.join(", "));
        }
        let is_null = |a: &&Value| str_of(a, "type") == "null";
        let nullable = alts.iter().any(|a| is_null(&a));
        let mut parts: Vec<String> = alts
            .iter()
            .filter(|a| !is_null(a))
            .map(|a| shape(a, used))
            .collect();
        if nullable {
            parts.push("`null`".to_owned());
        }
        return join_or(&parts);
    }

    let types: Vec<&str> = match obj.get("type") {
        Some(Value::String(t)) => vec![t.as_str()],
        Some(Value::Array(ts)) => ts.iter().filter_map(Value::as_str).collect(),
        _ => Vec::new(),
    };
    let mut parts: Vec<String> = types
        .iter()
        .filter(|t| **t != "null")
        .map(|t| typed_shape(t, obj, used))
        .collect();
    if parts.is_empty() && !types.contains(&"null") {
        parts.push("any JSON value".to_owned());
    }
    if types.contains(&"null") {
        parts.push("`null`".to_owned());
    }
    join_or(&parts)
}

/// A JSON text as an inline code span.
fn code(json: &str) -> String {
    format!("`{}`", json.replace('`', "'").replace('|', "\\|"))
}

/// The shape of a value of JSON type `ty` with the keywords of `obj`.
fn typed_shape(ty: &str, obj: &Map<String, Value>, used: &mut BTreeSet<String>) -> String {
    let mut notes: Vec<String> = Vec::new();
    let number = |key: &str| obj.get(key).map(Value::to_string);
    let base = match ty {
        "object" => {
            if let Some(props) = obj.get("properties").and_then(Value::as_object) {
                let required: BTreeSet<&str> = obj
                    .get("required")
                    .and_then(Value::as_array)
                    .map(|r| r.iter().filter_map(Value::as_str).collect())
                    .unwrap_or_default();
                let fields: Vec<String> = props
                    .iter()
                    .map(|(k, v)| {
                        format!(
                            "`{k}{}`: {}",
                            if required.contains(k.as_str()) { "" } else { "?" },
                            shape(v, used)
                        )
                    })
                    .collect();
                format!("object {{ {} }}", fields.join(", "))
            } else if let Some(values) = obj.get("additionalProperties").filter(|v| v.is_object()) {
                format!("map of {}", shape(values, used))
            } else {
                "object".to_owned()
            }
        }
        "array" => {
            if let Some(prefix) = obj.get("prefixItems").and_then(Value::as_array) {
                let items: Vec<String> = prefix.iter().map(|v| shape(v, used)).collect();
                format!("array of ({})", items.join(", "))
            } else if let Some(items) = obj.get("items") {
                format!("array of {}", shape(items, used))
            } else {
                "array".to_owned()
            }
        }
        other => other.to_owned(),
    };
    if let Some(f) = obj.get("format").and_then(Value::as_str) {
        notes.push(format!("format `{f}`"));
    }
    if let Some(n) = number("minimum") {
        notes.push(format!("min {n}"));
    }
    if let Some(n) = number("maximum") {
        notes.push(format!("max {n}"));
    }
    if let Some(n) = number("minLength") {
        notes.push(format!("at least {n} character(s)"));
    }
    if let Some(n) = number("maxLength") {
        notes.push(format!("at most {n} character(s)"));
    }
    if let Some(n) = number("minItems") {
        notes.push(format!("at least {n} item(s)"));
    }
    if let Some(n) = number("maxItems") {
        notes.push(format!("at most {n} item(s)"));
    }
    if let Some(n) = number("minProperties") {
        notes.push(format!("at least {n} propert(ies)"));
    }
    if obj.get("uniqueItems") == Some(&Value::Bool(true)) {
        notes.push("items unique".to_owned());
    }
    if let Some(p) = obj
        .get("pattern")
        .and_then(Value::as_str)
        .filter(|p| p.len() <= 48)
    {
        notes.push(format!("pattern `{}`", p.replace('`', "'").replace('|', "\\|")));
    }
    if notes.is_empty() {
        base
    } else {
        format!("{base} ({})", notes.join(", "))
    }
}

// ---------------------------------------------------------------------------------------------------------------
// Rules

#[derive(Deserialize)]
struct Catalogue {
    rules: Vec<Rule>,
    schemes: Vec<SchemeInfo>,
}

#[derive(Deserialize)]
struct SchemeInfo {
    name: String,
    purpose: String,
    lenient: bool,
}

#[derive(Deserialize)]
struct Rule {
    id: String,
    code: String,
    pack: String,
    title: String,
    kind: String,
    modes: Vec<String>,
    severity: String,
    release_severity: Option<String>,
    scope: String,
    supersedes: Vec<String>,
    release: String,
    waivable: bool,
    schemes: Vec<RuleScheme>,
}

#[derive(Deserialize)]
struct RuleScheme {
    name: String,
    online: bool,
    release: bool,
}

fn rule_pages(root: &Path, files: &mut BTreeMap<String, String>) -> Result<SummaryItems> {
    let text = read_lf(&root.join(CATALOGUE))?.with_context(|| format!("{CATALOGUE} is missing"))?;
    let catalogue: Catalogue = serde_json::from_str(&text).with_context(|| format!("parsing {CATALOGUE}"))?;
    let mut packs: BTreeMap<&str, Vec<&Rule>> = BTreeMap::new();
    for rule in &catalogue.rules {
        packs.entry(rule.pack.as_str()).or_default().push(rule);
    }
    let mut items = SummaryItems::new();
    let mut rows = String::new();
    for (pack, rules) in &packs {
        let file = format!("{}.md", pack.to_lowercase());
        files.insert(format!("{RULES_DIR}/{file}"), pack_page(pack, rules));
        items.push(((*pack).to_owned(), format!("{RULES_DIR}/{file}")));
        let _ = writeln!(
            rows,
            "| [`{pack}`]({file}) | {} | {} |",
            rules.len(),
            rules
                .iter()
                .map(|r| format!("[`{}`]({file}#{})", r.id, r.id.to_lowercase()))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }

    let schemes: Vec<String> = catalogue
        .schemes
        .iter()
        .map(|s| {
            format!(
                "| `{}` | {} | {} |",
                s.name,
                cell(&s.purpose),
                if s.lenient { "yes" } else { "no" }
            )
        })
        .collect();
    let mut page = String::new();
    let _ = write!(
        page,
        "# Rule reference\n\n{}\n\n\
         A rule checks one property of a project and reports findings with the rule's ID, for example `EW-TERM-002`. \
         Rules are grouped in packs; a check scheme selects the rules a run executes. This reference lists the {} \
         shipped rules of the rule registry, one page per pack, from the catalogue snapshot \
         [`{CATALOGUE}`]({}). The rule catalogue of the design is [doc 15 §4]({}).\n\n\
         What a page does not hold yet: the message text (the engine builds each message at run time from the \
         records it names), the quick fix, the standard reference by number and clause, an example and waiver \
         guidance (NFR-DOC-02). They arrive with the Fluent messages of the rules; until then each pack page links its \
         section of the catalogue.\n\n\
         ## Packs\n\n| Pack | Rules | IDs |\n|---|---|---|\n{rows}\n\
         ## Schemes\n\n| Scheme | Purpose | Lenient |\n|---|---|---|\n{}\n",
        header(CATALOGUE),
        catalogue.rules.len(),
        repo_link(CATALOGUE, None),
        repo_link(
            "docs/design/15-checks-revisions-collaboration.md",
            Some("4-rule-catalogue")
        ),
        schemes.join("\n"),
    );
    files.insert(format!("{RULES_DIR}/index.md"), page);
    Ok(items)
}

/// The page of one rule pack.
fn pack_page(pack: &str, rules: &[&Rule]) -> String {
    let mut out = format!("# Rule pack {pack}\n\n{}\n\n", header(CATALOGUE));
    let _ = write!(out, "{} rule(s) in this pack.", rules.len());
    if let Some((_, title, anchor)) = PACK_SECTIONS.iter().find(|(p, _, _)| p == &pack) {
        let _ = write!(
            out,
            " The catalogue entry of the pack is [doc 15 §{title}]({}).",
            repo_link("docs/design/15-checks-revisions-collaboration.md", Some(anchor)),
        );
    }
    out.push_str(
        "\n\n| ID | Title | Kind | Severity | Release severity | Modes | Scope |\n|---|---|---|---|---|---|---|\n",
    );
    for r in rules {
        let _ = writeln!(
            out,
            "| [`{}`](#{}) | {} | {} | {} | {} | {} | {} |",
            r.id,
            r.id.to_lowercase(),
            cell(&r.title),
            r.kind,
            r.severity,
            r.release_severity.as_deref().unwrap_or("same"),
            r.modes.join(", "),
            r.scope,
        );
    }
    out.push('\n');
    for r in rules {
        let supersedes: Vec<String> = r.supersedes.iter().map(|s| format!("`{s}`")).collect();
        let running = |online: bool| -> String {
            let names: Vec<String> = r
                .schemes
                .iter()
                .filter(|s| if online { s.online } else { s.release })
                .map(|s| format!("`{}`", s.name))
                .collect();
            if names.is_empty() {
                "none".to_owned()
            } else {
                names.join(", ")
            }
        };
        let _ = write!(
            out,
            "## {id}\n\n**{title}**\n\n\
             | Item | Value |\n|---|---|\n\
             | ID | `{id}` |\n\
             | Code | `{code}` |\n\
             | Pack | `{pack}` |\n\
             | Kind | {kind} |\n\
             | Severity | {severity} |\n\
             | Release severity | {release_severity} |\n\
             | Modes | {modes} |\n\
             | Scope | {scope} |\n\
             | Waivable | {waivable} |\n\
             | Pack content | {release} |\n\
             | Supersedes | {supersedes} |\n\
             | Runs in schemes, online mode | {online} |\n\
             | Runs in schemes, release mode | {release_mode} |\n\n",
            id = r.id,
            title = cell(&r.title),
            code = r.code,
            pack = r.pack,
            kind = r.kind,
            severity = r.severity,
            release_severity = r.release_severity.as_deref().unwrap_or("same as severity"),
            modes = r.modes.join(", "),
            scope = r.scope,
            waivable = if r.waivable { "yes" } else { "no" },
            release = r.release,
            supersedes = if supersedes.is_empty() {
                "none".to_owned()
            } else {
                supersedes.join(", ")
            },
            online = running(true),
            release_mode = running(false),
        );
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn items() -> SummaryItems {
        vec![("`a.b`".to_owned(), format!("{COMMANDS_DIR}/a.b.md"))]
    }

    #[test]
    fn summary_entries_are_regenerated_below_the_index_lines() {
        let text = format!(
            "# Summary\n\n- [Reference](reference/index.md)\n  - [Commands]({COMMANDS_DIR}/index.md)\n    - [`old`]({COMMANDS_DIR}/old.md)\n  - [Rules]({RULES_DIR}/index.md)\n    - [OLD]({RULES_DIR}/old.md)\n- [After](after.md)\n"
        );
        let packs = vec![("EW-X".to_owned(), format!("{RULES_DIR}/ew-x.md"))];
        let once = rewrite_summary(&text, &items(), &packs).unwrap();
        assert_eq!(
            once,
            format!(
                "# Summary\n\n- [Reference](reference/index.md)\n  - [Commands]({COMMANDS_DIR}/index.md)\n    - [`a.b`]({COMMANDS_DIR}/a.b.md)\n  - [Rules]({RULES_DIR}/index.md)\n    - [EW-X]({RULES_DIR}/ew-x.md)\n- [After](after.md)\n"
            )
        );
        assert_eq!(
            rewrite_summary(&once, &items(), &packs).unwrap(),
            once,
            "idempotent"
        );
        assert!(rewrite_summary("# Summary\n", &items(), &packs).is_err());
    }

    #[test]
    fn descriptions_are_made_markdown_safe() {
        assert_eq!(
            clean("One of [`DesignateTerminals`] with <kind> and `<kept>`."),
            "One of `DesignateTerminals` with &lt;kind> and `<kept>`."
        );
        assert_eq!(cell("a | b\nc"), "a \\| b c");
        assert_eq!(first_paragraph("one\ntwo\n\nthree"), "one two");
        assert_eq!(anchor("CmdUuid"), "cmduuid");
    }

    #[test]
    fn shapes_name_types_constraints_and_definitions() {
        let mut used = BTreeSet::new();
        assert_eq!(
            shape(
                &json!({"type": "integer", "format": "uint32", "minimum": 0}),
                &mut used
            ),
            "integer (format `uint32`, min 0)"
        );
        assert_eq!(
            shape(&json!({"type": ["integer", "null"], "minimum": 1}), &mut used),
            "integer (min 1) or `null`"
        );
        assert_eq!(
            shape(
                &json!({"type": "array", "items": {"$ref": "#/$defs/CmdUuid"}, "minItems": 1}),
                &mut used
            ),
            "array of [`CmdUuid`](#cmduuid) (at least 1 item(s))"
        );
        assert_eq!(used.into_iter().collect::<Vec<_>>(), ["CmdUuid"]);
        let mut used = BTreeSet::new();
        assert_eq!(
            shape(&json!({"oneOf": [{"const": "a"}, {"const": "b"}]}), &mut used),
            "one of `\"a\"`, `\"b\"`"
        );
        assert_eq!(
            shape(
                &json!({"anyOf": [{"type": "string"}, {"type": "null"}]}),
                &mut used
            ),
            "string or `null`"
        );
        assert_eq!(shape(&json!({}), &mut used), "any JSON value");
        assert_eq!(
            shape(
                &json!({"type": "object", "properties": {"a": {"type": "string"}, "b": {"type": "boolean"}}, "required": ["a"]}),
                &mut used
            ),
            "object { `a`: string, `b?`: boolean }"
        );
    }

    #[test]
    fn a_command_page_lists_parameters_types_and_exit_codes() {
        let entry = json!({"name": "x.y", "params_version": 1, "cost": "bulk", "undoable": true, "exposure": "edit",
            "stability": "preview", "aliases": [], "confirmation": "none", "schema": "x.y.schema.json"});
        let schema = json!({
            "$defs": {"Id": {"description": "An id.", "type": "string", "pattern": "^a$", "minLength": 1}},
            "description": "`x.y`: does a thing.\n\nRejected: nothing.",
            "properties": {"ids": {"description": "The ids.", "items": {"$ref": "#/$defs/Id"}, "type": "array"}},
            "required": ["ids"],
            "type": "object"
        });
        let consts = BTreeMap::from([("LIST", "`a`, `b`".to_owned())]);
        let page = command_page(&entry, &schema, &consts);
        assert!(page.starts_with("# `x.y`\n"), "{page}");
        assert!(
            page.contains("| `ids` | array of [`Id`](#id) | yes |  | The ids. |"),
            "{page}"
        );
        assert!(
            page.contains("### Id\n\nAn id.\n\nType: string (at least 1 character(s), pattern `^a$`)"),
            "{page}"
        );
        assert!(page.contains("## Exit codes"), "{page}");
        assert!(page.contains("bulk command"), "{page}");
        let listed = json!({"description": "`path` is one of [`LIST`] (else invalid)."});
        let page = command_page(&entry, &listed, &consts);
        assert!(
            page.contains("`path` is one of `a`, `b` (else invalid)."),
            "{page}"
        );
    }

    #[test]
    fn a_rule_pack_page_has_one_section_per_rule() {
        let rule = Rule {
            id: "EW-TERM-002".into(),
            code: "001002".into(),
            pack: "EW-TERM".into(),
            title: "Duplicate designation".into(),
            kind: "conflict".into(),
            modes: vec!["online".into(), "prevent".into()],
            severity: "error".into(),
            release_severity: None,
            scope: "strip".into(),
            supersedes: vec![],
            release: "MVP".into(),
            waivable: true,
            schemes: vec![
                RuleScheme {
                    name: "drafting".into(),
                    online: true,
                    release: false,
                },
                RuleScheme {
                    name: "full".into(),
                    online: true,
                    release: true,
                },
            ],
        };
        let page = pack_page("EW-TERM", &[&rule]);
        assert!(
            page.contains("## EW-TERM-002\n\n**Duplicate designation**"),
            "{page}"
        );
        assert!(
            page.contains("| Runs in schemes, online mode | `drafting`, `full` |"),
            "{page}"
        );
        assert!(
            page.contains("| Runs in schemes, release mode | `full` |"),
            "{page}"
        );
        assert!(page.contains("#44-ew-term-and-ew-pot"), "{page}");
    }

    #[test]
    fn the_committed_pages_are_current() {
        // The committed reference pages equal what the committed sources generate (`docs-gen --check`).
        assert!(run(&crate::workspace_root(), true).unwrap());
    }
}
